riseB := valveBStart AND NOT prevValveBStart;
riseC := valveCStart AND NOT prevValveCStart;
riseD := valveDStart AND NOT prevValveDStart;
riseMix := mixMotorStart AND NOT prevMixMotorStart;
riseAuto := autoStart AND NOT prevAutoStart;
modeChanged := opeMode <> prevOpeMode;

// Default? We'll set outputs according to branches.
IF NOT estop THEN
    valveARun := FALSE; ...
    mixARunLatch := FALSE? Need latches separate from outputs? We can use outputs as manual latches, but in auto output overridden. Better have manual latch variables mValveARun etc. At manual branch assign outputs = m*. At auto outputs = phase. Reset latches on estop/mode change.
    mValveARun := FALSE; mValveBRun := FALSE; ... mMixMotorRun := FALSE;
    phase := E_PUB015_Phase.IDLE;
ELSIF modeChanged THEN
    // safe, mode changed: clear latches and sequence
    mValveARun := FALSE; ...
    phase := E_PUB015_Phase.IDLE;
    // then continue? In same scan, if new opeMode auto and autoStart rising? Should maybe process below. But if modeChanged we clear then process. Need avoid output defaults. We can not use ELSIF because need process after clear. Structure:
IF NOT estop THEN reset; then outputs false; 
ELSE
   IF modeChanged THEN reset latches/phase; END_IF;
   IF opeMode THEN
       // auto transitions and outputs
